import 'package:equatable/equatable.dart';

/// Model representing client statistics and insights
class ClientStats extends Equatable {
  final String clientId;
  final String clientName;
  final String? phoneNumber;
  final String? email;
  final String? profilePictureUrl;
  final int totalAppointments;
  final int completedAppointments;
  final int cancelledAppointments;
  final double totalSpent;
  final DateTime firstVisit;
  final DateTime lastVisit;
  final List<String> favoriteServices;

  const ClientStats({
    required this.clientId,
    required this.clientName,
    this.phoneNumber,
    this.email,
    this.profilePictureUrl,
    required this.totalAppointments,
    required this.completedAppointments,
    required this.cancelledAppointments,
    required this.totalSpent,
    required this.firstVisit,
    required this.lastVisit,
    required this.favoriteServices,
  });

  @override
  List<Object?> get props => [
    clientId,
    clientName,
    phoneNumber,
    email,
    profilePictureUrl,
    totalAppointments,
    completedAppointments,
    cancelledAppointments,
    totalSpent,
    firstVisit,
    lastVisit,
    favoriteServices,
  ];

  /// Calculate completion rate percentage
  double get completionRate {
    if (totalAppointments == 0) return 0.0;
    return (completedAppointments / totalAppointments) * 100;
  }

  /// Check if client is a regular (3+ completed appointments)
  bool get isRegularClient => completedAppointments >= 3;

  /// Calculate average spending per visit
  double get averageSpending {
    if (completedAppointments == 0) return 0.0;
    return totalSpent / completedAppointments;
  }

  ClientStats copyWith({
    String? clientId,
    String? clientName,
    String? phoneNumber,
    String? email,
    String? profilePictureUrl,
    int? totalAppointments,
    int? completedAppointments,
    int? cancelledAppointments,
    double? totalSpent,
    DateTime? firstVisit,
    DateTime? lastVisit,
    List<String>? favoriteServices,
  }) {
    return ClientStats(
      clientId: clientId ?? this.clientId,
      clientName: clientName ?? this.clientName,
      phoneNumber: phoneNumber ?? this.phoneNumber,
      email: email ?? this.email,
      profilePictureUrl: profilePictureUrl ?? this.profilePictureUrl,
      totalAppointments: totalAppointments ?? this.totalAppointments,
      completedAppointments:
      completedAppointments ?? this.completedAppointments,
      cancelledAppointments:
      cancelledAppointments ?? this.cancelledAppointments,
      totalSpent: totalSpent ?? this.totalSpent,
      firstVisit: firstVisit ?? this.firstVisit,
      lastVisit: lastVisit ?? this.lastVisit,
      favoriteServices: favoriteServices ?? this.favoriteServices,
    );
  }
}

import 'package:cloud_firestore/cloud_firestore.dart';

/// Simplified client model for owner's client management
/// 
/// Only contains essential info:
/// - Who they are (name, photo, phone)
/// - When they last visited
/// - How many times they've visited (for sorting regulars)
class RegularClient {
  final String id;
  final String name;
  final String? phone;
  final String? photoUrl;
  final DateTime lastVisit;
  final int visitCount;

  const RegularClient({
    required this.id,
    required this.name,
    this.phone,
    this.photoUrl,
    required this.lastVisit,
    required this.visitCount,
  });

  /// Create from Firestore user doc + aggregated appointment data
  factory RegularClient.fromData({
    required String userId,
    required String userName,
    String? userPhone,
    String? userPhotoUrl,
    required DateTime lastVisitDate,
    required int totalVisits,
  }) {
    return RegularClient(
      id: userId,
      name: userName,
      phone: userPhone,
      photoUrl: userPhotoUrl,
      lastVisit: lastVisitDate,
      visitCount: totalVisits,
    );
  }

  /// Get formatted last visit text
  String get lastVisitFormatted {
    final now = DateTime.now();
    final diff = now.difference(lastVisit);

    if (diff.inDays == 0) return 'Today';
    if (diff.inDays == 1) return 'Yesterday';
    if (diff.inDays < 7) return '${diff.inDays}d ago';
    if (diff.inDays < 30) return '${(diff.inDays / 7).floor()}w ago';
    if (diff.inDays < 60) return '1mo ago';
    return '${(diff.inDays / 30).floor()}mo ago';
  }

  /// Check if client is a regular (5+ visits)
  bool get isRegular => visitCount >= 5;
}

