import '../../domain/repositories/client_management_repository_new (1).dart';
import 'client_management_event_new.dart';
import 'client_management_state_new.dart';

class ClientManagementBloc extends Bloc<ClientManagementEvent, ClientManagementState> {
  final ClientManagementRepository _repository;
  final FirestoreService _firestoreService;
  final AuthBloc _authBloc;
  String? _currentSalonId;

  ClientManagementBloc({
    required ClientManagementRepository repository,
    required FirestoreService firestoreService,
    required AuthBloc authBloc,
  })  : _repository = repository,
        _firestoreService = firestoreService,
        _authBloc = authBloc,
        super(const ClientManagementInitial()) {
    on<LoadClients>(_onLoadClients);
    on<SearchClients>(_onSearchClients);
    on<RefreshClients>(_onRefreshClients);
  }

  Future<void> _onLoadClients(
    LoadClients event,
    Emitter<ClientManagementState> emit,
  ) async {
    emit(const ClientManagementLoading());
    await _loadData(emit);
  }

  Future<void> _onSearchClients(
    SearchClients event,
    Emitter<ClientManagementState> emit,
  ) async {
    final currentState = state;

    // If not loaded yet, load first
    if (currentState is! ClientManagementLoaded) {
      await _loadData(emit);
      if (state is! ClientManagementLoaded) return;
    }

    final loadedState = state as ClientManagementLoaded;

    // Empty query = clear search
    if (event.query.trim().isEmpty) {
      emit(loadedState.copyWith(clearSearch: true));
      return;
    }

    try {
      final salonId = await _getSalonId();
      final results = await _repository.searchClients(salonId, event.query);

      emit(loadedState.copyWith(searchResults: results));
    } catch (e, s) {
      log.e('Error searching clients', error: e, stackTrace: s);
      // Don't emit error, just keep current state
    }
  }

  Future<void> _onRefreshClients(
    RefreshClients event,
    Emitter<ClientManagementState> emit,
  ) async {
    // Don't show loading, just refresh in background
    await _loadData(emit);
  }

  Future<void> _loadData(Emitter<ClientManagementState> emit) async {
    try {
      log.i('Loading client management data');

      final salonId = await _getSalonId();

      // Fetch both regulars and recent bookings in parallel
      final results = await Future.wait([
        _repository.getRegularClients(salonId),
        _repository.getRecentBookings(salonId),
      ]);

      final regulars = results[0];
      final bookings = results[1];

      log.i('Loaded ${regulars.length} regulars, ${bookings.length} recent bookings');

      emit(ClientManagementLoaded(
        regularClients: regulars,
        recentBookings: bookings,
      ));
    } catch (e, s) {
      log.e('Error loading client data', error: e, stackTrace: s);
      emit(ClientManagementError('Failed to load clients: ${e.toString()}'));
    }
  }

  /// Get salon ID with caching
  Future<String> _getSalonId() async {
    if (_currentSalonId != null) return _currentSalonId!;

    final authState = _authBloc.state;
    if (authState is! Authenticated) {
      throw Exception('User not authenticated');
    }

    final salon = await _firestoreService.getSalonForOwner(
      ownerId: authState.user.uid,
    );

    if (salon == null) {
      throw Exception('No salon found for owner');
    }

    _currentSalonId = salon.id;
    return salon.id;
  }
}

import 'package:equatable/equatable.dart';

abstract class ClientManagementEvent extends Equatable {
  const ClientManagementEvent();

  @override
  List<Object?> get props => [];
}

/// Load all data (regulars + recent bookings)
class LoadClients extends ClientManagementEvent {
  const LoadClients();
}

/// Search clients by name or phone
class SearchClients extends ClientManagementEvent {
  final String query;

  const SearchClients(this.query);

  @override
  List<Object?> get props => [query];
}

/// Refresh data (pull to refresh)
class RefreshClients extends ClientManagementEvent {
  const RefreshClients();
}

import 'package:equatable/equatable.dart';
import 'package:pendeza/shared/models/appointment_model.dart';
import '../../domain/models/regular_client.dart';

abstract class ClientManagementState extends Equatable {
  const ClientManagementState();

  @override
  List<Object?> get props => [];
}

/// Initial state
class ClientManagementInitial extends ClientManagementState {
  const ClientManagementInitial();
}

/// Loading state
class ClientManagementLoading extends ClientManagementState {
  const ClientManagementLoading();
}

/// Loaded state with all data
class ClientManagementLoaded extends ClientManagementState {
  final List<RegularClient> regularClients; // Top clients (5+ visits)
  final List<AppointmentModel> recentBookings; // Last 10 appointments
  final List<RegularClient>? searchResults; // Populated during search

  const ClientManagementLoaded({
    required this.regularClients,
    required this.recentBookings,
    this.searchResults,
  });

  /// Check if currently searching
  bool get isSearching => searchResults != null;

  @override
  List<Object?> get props => [regularClients, recentBookings, searchResults];

  /// Create copy with updated search results
  ClientManagementLoaded copyWith({
    List<RegularClient>? regularClients,
    List<AppointmentModel>? recentBookings,
    List<RegularClient>? searchResults,
    bool clearSearch = false,
  }) {
    return ClientManagementLoaded(
      regularClients: regularClients ?? this.regularClients,
      recentBookings: recentBookings ?? this.recentBookings,
      searchResults: clearSearch ? null : (searchResults ?? this.searchResults),
    );
  }
}

/// Error state
class ClientManagementError extends ClientManagementState {
  final String message;

  const ClientManagementError(this.message);

  @override
  List<Object?> get props => [message];
}

