      margin: const EdgeInsets.only(bottom: AppConstants.padM),
      padding: const EdgeInsets.all(AppConstants.padM),
      decoration: BoxDecoration(
        color: theme.colorScheme.surface,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(
          color: theme.colorScheme.outline.withOpacity(0.1),
        ),
      ),
      child: Row(
        children: [
          // Client avatar
          ProfileAvatar(
            fullName: booking.clientName ?? 'Client',
            imageUrl: null,
            radius: 24,
          ),
          const SizedBox(width: AppConstants.padM),

          // Booking info
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                // Client name
                Text(
                  booking.clientName ?? 'Client',
                  style: theme.textTheme.titleSmall?.copyWith(
                    fontWeight: FontWeight.bold,
                  ),
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                ),
                const SizedBox(height: 4),

                // Service names
                Text(
                  _getServicesSummary(),
                  style: theme.textTheme.bodySmall?.copyWith(
                    color: theme.colorScheme.onSurface.withOpacity(0.7),
                  ),
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                ),
                const SizedBox(height: 4),

                // Date and status
                Row(
                  children: [
                    Icon(
                      CupertinoIcons.calendar,
                      size: 12,
                      color: theme.colorScheme.onSurface.withOpacity(0.5),
                    ),
                    const SizedBox(width: 4),
                    Text(
                      DateFormat('MMM d, h:mm a').format(booking.startTime),
                      style: theme.textTheme.labelSmall?.copyWith(
                        color: theme.colorScheme.onSurface.withOpacity(0.6),
                      ),
                    ),
                    const SizedBox(width: 8),
                    _StatusBadge(status: booking.status),
                  ],
                ),
              ],
            ),
          ),

          // Price
          Text(
            'TZS ${booking.totalPrice.toStringAsFixed(0)}',
            style: theme.textTheme.titleSmall?.copyWith(
              fontWeight: FontWeight.bold,
              color: theme.colorScheme.primary,
            ),
          ),
        ],
      ),
    );
  }

  String _getServicesSummary() {
    if (booking.serviceNames.isEmpty) return 'Services';
    if (booking.serviceNames.length == 1) return booking.serviceNames.first;
    return '${booking.serviceNames.first} +${booking.serviceNames.length - 1}';
  }
}

class _StatusBadge extends StatelessWidget {
  final String status;

  const _StatusBadge({required this.status});

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final statusLower = status.toLowerCase();

    Color bgColor;
    Color textColor;
    IconData icon;

    switch (statusLower) {
      case 'completed':
        bgColor = Colors.green.withOpacity(0.15);
        textColor = Colors.green;
        icon = CupertinoIcons.check_mark_circled_solid;
        break;
      case 'confirmed':
        bgColor = Colors.blue.withOpacity(0.15);
        textColor = Colors.blue;
        icon = CupertinoIcons.checkmark_seal_fill;
        break;
      case 'pending payment':
        bgColor = Colors.orange.withOpacity(0.15);
        textColor = Colors.orange;
        icon = CupertinoIcons.time_solid;
        break;
      case 'cancelled':
        bgColor = Colors.red.withOpacity(0.15);
        textColor = Colors.red;
        icon = CupertinoIcons.xmark_circle_fill;
        break;
      default:
        bgColor = theme.colorScheme.surfaceContainerHighest;
        textColor = theme.colorScheme.onSurface;
        icon = CupertinoIcons.circle_fill;
    }

    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
      decoration: BoxDecoration(
        color: bgColor,
        borderRadius: BorderRadius.circular(8),
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(icon, size: 10, color: textColor),
          const SizedBox(width: 4),
          Text(
            status,
            style: theme.textTheme.labelSmall?.copyWith(
              color: textColor,
              fontWeight: FontWeight.w600,
              fontSize: 10,
            ),
          ),
        ],
      ),
    );
  }
}

